<script lang="ts">import {untrack} from 'svelte';import Arrow from './Arrow.svelte';import {localizedPath} from '$lib/series/i18n';import type {loadPrompts} from '$lib/server/series';let {data}:{data:ReturnType<typeof loadPrompts>}=$props();let ui=$derived(data.ui);let query=$state(untrack(()=>data.query));let level=$state(untrack(()=>data.level));let filtered=$derived(data.posts.filter(p=>(level==='all'||p.level===level)&&[p.title,p.criterion,p.summary].join(' ').toLowerCase().includes(query.toLowerCase())));</script>
<svelte:head><title>{ui.libraryTitle} — jangwook.net</title><meta name="description" content={ui.libraryDescription}/></svelte:head>
<section class="wrap page-intro"><p class="eyebrow">THE PROMPT LIBRARY</p><h1>{ui.libraryTitle}</h1><p class="lead">{ui.libraryLead}</p></section><section class="wrap section prompt-library"><form class="search-tools" method="GET" action={localizedPath('/prompts',data.lang)} role="search" aria-label={ui.searchLabel}><div><label for="prompt-search">{ui.searchInput}</label><input id="prompt-search" type="search" name="q" bind:value={query} placeholder={ui.searchPlaceholder}/></div><div><label for="prompt-level">{ui.level}</label><select id="prompt-level" name="level" bind:value={level}><option value="all">{ui.all}</option><option>A</option><option>AA</option><option>AAA</option></select></div><button class="button" type="submit">{ui.search}</button></form><p class="results-count" role="status">{filtered.length} {ui.promptCount}</p><div class="prompt-grid">{#each filtered as p}<a class="prompt-card" href={localizedPath('/series/accessibility/'+p.slug,data.lang)+(p.available?'#evaluation-prompt':'')}><span class="eyebrow">{p.criterion?'WCAG '+p.criterion+' / LEVEL '+p.level:'OVERVIEW'}</span><h2>{p.title}</h2><p>{p.summary}</p><span class="prompt-card-link">{p.available?ui.explanation:ui.planned} <Arrow/></span></a>{/each}</div>{#if filtered.length===0}<p class="empty-state">{ui.empty}</p>{/if}</section>
